```java
// ─── File: src/main/java/com/bank/core/AccountKey.java ───
package com.bank.core;

import java.util.Objects;

// Immutable (final class, final fields, no setters) → stable hashCode as a key.
public final class AccountKey {
    private final String branchCode;
    private final String accountNumber;

    public AccountKey(String branchCode, String accountNumber) {
        this.branchCode = Objects.requireNonNull(branchCode);
        this.accountNumber = Objects.requireNonNull(accountNumber);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof AccountKey)) return false;
        AccountKey k = (AccountKey) o;
        return Objects.equals(branchCode, k.branchCode)
            && Objects.equals(accountNumber, k.accountNumber);
    }
    @Override
    public int hashCode() { return Objects.hash(branchCode, accountNumber); }

    @Override
    public String toString() { return branchCode + ":" + accountNumber; }
}
```

