// ─── File: src/main/java/com/bank/core/HashMapKeyDemo.java ───
package com.bank.core;

import java.util.HashMap;
import java.util.Map;
import java.util.logging.*;

public class HashMapKeyDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Map<AccountKey, String> tierByAccount = new HashMap<>();

        AccountKey rajesh = new AccountKey("MUM", "SAV2001");
        tierByAccount.put(rajesh, "PREMIUM");
        log.info(() -> "Stored tier for " + rajesh);

        // Lookup with a DIFFERENT but EQUAL key instance → works.
        String tier = tierByAccount.get(new AccountKey("MUM", "SAV2001"));
        log.info(() -> "Lookup with equal key → " + tier);

        // Immutable key stays reachable: same instance used again.
        boolean present = tierByAccount.containsKey(new AccountKey("MUM", "SAV2001"));
        log.info(() -> "containsKey(equal) → " + present);

        // A different account does not collide logically.
        String missing = tierByAccount.get(new AccountKey("MUM", "CUR3001"));
        log.info(() -> "Lookup for CUR3001 → " + missing);
    }
}
```
